{
  "items": [
    {
      "path": "tools.opencode.read_mcp_resource",
      "description": "Read one MCP resource by server and URI. Not for local files. Always return the full contents rather than slicing or filtering them; oversized output is truncated automatically and the full content is saved to a file you can read. Images and PDFs are shown to you directly.",
      "signature": "tools.opencode.read_mcp_resource({
  /** The server field of the discovered resource. */
  server: string,
  /** Exact resource URI from discovery, an expanded uriTemplate, or the user. */
  uri: string,
}): Promise<{
  server: string,
  uri: string,
  contents: Array<{
        type: "text",
        uri: string,
        text: string,
        mimeType?: string,
      } | {
        type: "blob",
        uri: string,
        blob: string,
        mimeType?: string,
      }>,
}>"
    },
    {
      "path": "tools.opencode.list_mcp_resources",
      "description": "List documents, records, and other data exposed by MCP servers. Use this when the user refers to something that is not a local file, such as a URI with a custom scheme, then load a match with read_mcp_resource. Each entry names the server to read it from. Templates are resources addressed by a parameter such as a record ID; fill in the uriTemplate placeholders before reading.",
      "signature": "tools.opencode.list_mcp_resources({
  /** MCP server name as configured. Omit to list every server. */
  server?: string,
}): Promise<{
  resources: Array<{
      server: string,
      name: string,
      uri: string,
      description?: string,
      mimeType?: string,
    }>,
  templates: Array<{
      server: string,
      name: string,
      uriTemplate: string,
      description?: string,
      mimeType?: string,
    }>,
}>"
    },
    {
      "path": "tools.elevenlabs.add_knowledge_base_to_agent",
      "description": "Add a knowledge base to ElevenLabs workspace. Allowed types are epub, pdf, docx, txt, html.

    ⚠️ COST WARNING: This tool makes an API call to ElevenLabs which may incur costs. Only use when explicitly requested by the user.

    Args:
        agent_id: ID of the agent to add the knowledge base to.
        knowledge_base_name: Name of the knowledge base.
        url: URL of the knowledge base.
        input_file_path: Path to the file to add to the knowledge base.
        text: Text to add to the knowledge base.
    ",
      "signature": "tools.elevenlabs.add_knowledge_base_to_agent({
  agent_id: string,
  knowledge_base_name: string,
  /** @default null */
  url?: string | null,
  /** @default null */
  input_file_path?: string | null,
  /** @default null */
  text?: string | null,
}): Promise<{
  type: "text",
  text: string,
  /** @default null */
  annotations?: {
      /** @default null */
      audience?: Array<"user" | "assistant"> | null,
      /** @default null */
      priority?: number | null,
    } | null,
  /** @default null */
  _meta?: {} | null,
}>"
    },
    {
      "path": "tools.elevenlabs.compose_music",
      "description": "Convert a prompt to music and save the output audio file to a given directory.
    Directory is optional, if not provided, the output file will be saved to $HOME/Desktop. Saves output file to directory (default: $HOME/Desktop).

    Two models are supported:
    - music_v2 (default): latest model. Composition plans use a `chunks` array where each chunk is either a `GenerationChunk` (text, duration_ms, positive_styles, negative_styles, context_adherence, optional conditioning_ref + condition_strength) or an `AudioRefChunk` ({song_id, range: {start_ms, end_ms}}) for inpainting. Inpainting also requires the source song to have been stored — call this tool with store_for_inpainting=True or use upload_music_for_inpainting first to get a song_id.
    - music_v1: legacy model. Composition plans use positive_global_styles, negative_global_styles, sections.

    Args:
        prompt: Prompt to convert to music. Must provide either prompt or composition_plan.
        output_directory: Directory to save the output audio file
        composition_plan: Composition plan dict. Shape depends on model_id (see above). Must provide either prompt or composition_plan.
        music_length_ms: Length of the generated music in milliseconds (3000-600000). Cannot be used if composition_plan is provided.
        model_id: Which music model to use. One of "music_v1" or "music_v2". Defaults to "music_v2".
        force_instrumental: If True, the model will avoid generating lyrics/vocals.
        store_for_inpainting: If True, the generated song is stored server-side and the returned song_id can be used in later inpainting calls (as an AudioRefChunk.song_id, or conditioning_ref).
        seed: Optional integer seed for reproducible generation (music_v2 only).

    ⚠️ COST WARNING: This tool makes an API call to ElevenLabs which may incur costs. Only use when explicitly requested by the user.",
      "signature": "tools.elevenlabs.compose_music({
  /** @default null */
  prompt?: string | null,
  /** @default null */
  output_directory?: string | null,
  /** @default null */
  composition_plan?: {} | null,
  /** @default null */
  music_length_ms?: number | null,
  /** @default "music_v2" */
  model_id?: "music_v1" | "music_v2",
  /** @default false */
  force_instrumental?: boolean,
  /** @default false */
  store_for_inpainting?: boolean,
  /** @default null */
  seed?: number | null,
}): Promise<{
  result: {
      type: "text",
      text: string,
      /** @default null */
      annotations?: {
          /** @default null */
          audience?: Array<"user" | "assistant"> | null,
          /** @default null */
          priority?: number | null,
        } | null,
      /** @default null */
      _meta?: {} | null,
    } | {
      type: "resource",
      resource: {
          /** @format uri @minLength 1 */
          uri: string,
          /** @default null */
          mimeType?: string | null,
          /** @default null */
          _meta?: {} | null,
          text: string,
        } | {
          /** @format uri @minLength 1 */
          uri: string,
          /** @default null */
          mimeType?: string | null,
          /** @default null */
          _meta?: {} | null,
          blob: string,
        },
      /** @default null */
      annotations?: {
          /** @default null */
          audience?: Array<"user" | "assistant"> | null,
          /** @default null */
          priority?: number | null,
        } | null,
      /** @default null */
      _meta?: {} | null,
    },
}>"
    },
    {
      "path": "tools.elevenlabs.isolate_audio",
      "description": "Isolate audio from a file. Saves output file to directory (default: $HOME/Desktop).

    ⚠️ COST WARNING: This tool makes an API call to ElevenLabs which may incur costs. Only use when explicitly requested by the user.
    ",
      "signature": "tools.elevenlabs.isolate_audio({
  input_file_path: string,
  /** @default null */
  output_directory?: string | null,
}): Promise<{
  result: {
      type: "text",
      text: string,
      /** @default null */
      annotations?: {
          /** @default null */
          audience?: Array<"user" | "assistant"> | null,
          /** @default null */
          priority?: number | null,
        } | null,
      /** @default null */
      _meta?: {} | null,
    } | {
      type: "resource",
      resource: {
          /** @format uri @minLength 1 */
          uri: string,
          /** @default null */
          mimeType?: string | null,
          /** @default null */
          _meta?: {} | null,
          text: string,
        } | {
          /** @format uri @minLength 1 */
          uri: string,
          /** @default null */
          mimeType?: string | null,
          /** @default null */
          _meta?: {} | null,
          blob: string,
        },
      /** @default null */
      annotations?: {
          /** @default null */
          audience?: Array<"user" | "assistant"> | null,
          /** @default null */
          priority?: number | null,
        } | null,
      /** @default null */
      _meta?: {} | null,
    },
}>"
    }
  ],
